namespace sv_b6f75a8db4a146569179edac05e70b7a.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@using sv_b6f75a8db4a146569179edac05e70b7a.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    @* Step Indicator Bar *@
    <div class="step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                <div class="step-circle">
                    @if (stepIndex < CurrentStep)
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@StepNames[stepIndex]</div>
            </div>
            @if (i < StepNames.Length - 1)
            {
                <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
            }
        }
    </div>

    @* Validation Errors *@
    @if (Errors.Any())
    {
        <div class="validation-errors">
            <ul>
                @foreach (var error in Errors)
                {
                    <li>@error</li>
                }
            </ul>
        </div>
    }

    @* Step Content *@
    <div class="step-content">
        @switch (CurrentStep)
        {
            case 0:
                @RenderPersonalInfo()
                break;
            case 1:
                @RenderWorkHistory()
                break;
            case 2:
                @RenderReferences()
                break;
            case 3:
                @RenderCoverLetter()
                break;
            case 4:
                @RenderReviewSubmit()
                break;
        }
    </div>
</div>

@* Step 1: Personal Info *@
@{
    RenderFragment RenderPersonalInfo() => @<div class="form-section">
        <h2>Personal Information</h2>
        <div class="form-group">
            <label for="fullName">Full Name *</label>
            <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" placeholder="Enter your full name" />
        </div>
        <div class="form-group">
            <label for="email">Email *</label>
            <input id="email" type="email" @bind="Email" @bind:event="oninput" placeholder="Enter your email" />
        </div>
        <div class="form-group">
            <label for="phone">Phone *</label>
            <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" placeholder="Enter your phone number" />
        </div>
        <div class="form-group">
            <label for="address">Address *</label>
            <textarea id="address" @bind="Address" @bind:event="oninput" placeholder="Enter your address"></textarea>
        </div>
        <div class="form-buttons">
            <button class="btn-next" @onclick="NextStep" disabled="@IsProcessing">
                @if (IsProcessing) { <span>Validating...</span> } else { <span>Next</span> }
            </button>
        </div>
    </div>;
}

@* Step 2: Work History *@
@{
    RenderFragment RenderWorkHistory() => @<div class="form-section">
        <h2>Work History</h2>
        @for (int i = 0; i < WorkEntries.Count; i++)
        {
            var index = i;
            <div class="work-entry-card">
                <div class="work-entry-header">
                    <h3>Position @(index + 1)</h3>
                    @if (WorkEntries.Count > 1)
                    {
                        <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                    }
                </div>
                <div class="form-group">
                    <label>Company Name *</label>
                    <input type="text" value="@WorkEntries[index].Company" @onchange="(e) => UpdateWorkEntry(index, company: e.Value?.ToString())" />
                </div>
                <div class="form-group">
                    <label>Job Title *</label>
                    <input type="text" value="@WorkEntries[index].Title" @onchange="(e) => UpdateWorkEntry(index, title: e.Value?.ToString())" />
                </div>
                <div class="form-row">
                    <div class="form-group">
                        <label>Start Date *</label>
                        <input type="date" value="@WorkEntries[index].StartDate.ToString("yyyy-MM-dd")" @onchange="(e) => UpdateWorkEntryStartDate(index, e.Value?.ToString())" />
                    </div>
                    <div class="form-group">
                        <label>End Date</label>
                        <input type="date" value="@WorkEntries[index].EndDate?.ToString("yyyy-MM-dd")" @onchange="(e) => UpdateWorkEntryEndDate(index, e.Value?.ToString())" disabled="@WorkEntries[index].IsCurrent" />
                    </div>
                </div>
                <div class="form-group checkbox-group">
                    <input type="checkbox" id="current-@index" checked="@WorkEntries[index].IsCurrent" @onchange="(e) => ToggleCurrentPosition(index, (bool)(e.Value ?? false))" />
                    <label for="current-@index">I currently work here</label>
                </div>
                <div class="form-group">
                    <label>Description *</label>
                    <textarea value="@WorkEntries[index].Description" @onchange="(e) => UpdateWorkEntry(index, description: e.Value?.ToString())"></textarea>
                </div>
            </div>
        }
        <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
        <div class="form-buttons">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextStep">Next</button>
        </div>
    </div>;
}

@* Step 3: References *@
@{
    RenderFragment RenderReferences() => @<div class="form-section">
        <h2>References</h2>
        @for (int i = 0; i < ReferenceEntries.Count; i++)
        {
            var index = i;
            <div class="reference-card">
                <div class="work-entry-header">
                    <h3>Reference @(index + 1)</h3>
                    @if (ReferenceEntries.Count > 2)
                    {
                        <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                    }
                </div>
                <div class="form-group">
                    <label>Name *</label>
                    <input type="text" value="@ReferenceEntries[index].Name" @onchange="(e) => UpdateReference(index, name: e.Value?.ToString())" />
                </div>
                <div class="form-group">
                    <label>Relationship *</label>
                    <input type="text" value="@ReferenceEntries[index].Relationship" @onchange="(e) => UpdateReference(index, relationship: e.Value?.ToString())" />
                </div>
                <div class="form-group">
                    <label>Email *</label>
                    <input type="email" value="@ReferenceEntries[index].Email" @onchange="(e) => UpdateReference(index, email: e.Value?.ToString())" />
                </div>
                <div class="form-group">
                    <label>Phone *</label>
                    <input type="tel" value="@ReferenceEntries[index].Phone" @onchange="(e) => UpdateReference(index, phone: e.Value?.ToString())" />
                </div>
            </div>
        }
        @if (ReferenceEntries.Count < 3)
        {
            <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
        }
        <div class="form-buttons">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextStep">Next</button>
        </div>
    </div>;
}

@* Step 4: Cover Letter *@
@{
    RenderFragment RenderCoverLetter() => @<div class="form-section">
        <h2>Cover Letter</h2>
        <div class="form-group">
            <label for="coverLetter">Write your cover letter *</label>
            <textarea id="coverLetter" class="cover-letter-textarea" @bind="CoverLetterText" @bind:event="oninput" maxlength="2000" placeholder="Tell us why you're a great fit for this role..."></textarea>
            <div class="character-count">@CoverLetterText.Length / 2000 characters</div>
        </div>
        <div class="form-buttons">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextStep">Next</button>
        </div>
    </div>;
}

@* Step 5: Review & Submit *@
@{
    RenderFragment RenderReviewSubmit() => @<div class="form-section">
        @if (IsSubmitted)
        {
            <div class="submission-confirmation">
                <div class="success-icon">&#10003;</div>
                <h2>Application Submitted Successfully!</h2>
                <p>Your application ID is: <strong>@ApplicationId</strong></p>
                <p>We'll be in touch soon. Thank you for applying!</p>
            </div>
        }
        else
        {
            <h2>Review & Submit</h2>

            <div class="review-section">
                <div class="review-header">
                    <h3>Personal Information</h3>
                    <button class="btn-edit" @onclick="() => GoToStep(0)">Edit</button>
                </div>
                <dl>
                    <dt>Full Name</dt><dd>@FullName</dd>
                    <dt>Email</dt><dd>@Email</dd>
                    <dt>Phone</dt><dd>@Phone</dd>
                    <dt>Address</dt><dd>@Address</dd>
                </dl>
            </div>

            <div class="review-section">
                <div class="review-header">
                    <h3>Work History</h3>
                    <button class="btn-edit" @onclick="() => GoToStep(1)">Edit</button>
                </div>
                @foreach (var entry in WorkEntries)
                {
                    <div class="review-work-entry">
                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                        <br />
                        <span>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span>
                        <p>@entry.Description</p>
                    </div>
                }
            </div>

            <div class="review-section">
                <div class="review-header">
                    <h3>References</h3>
                    <button class="btn-edit" @onclick="() => GoToStep(2)">Edit</button>
                </div>
                @foreach (var reference in ReferenceEntries)
                {
                    <div class="review-reference">
                        <strong>@reference.Name</strong> (@reference.Relationship)
                        <br />
                        <span>@reference.Email | @reference.Phone</span>
                    </div>
                }
            </div>

            <div class="review-section">
                <div class="review-header">
                    <h3>Cover Letter</h3>
                    <button class="btn-edit" @onclick="() => GoToStep(3)">Edit</button>
                </div>
                <p class="cover-letter-preview">@CoverLetterText</p>
            </div>

            <div class="form-buttons">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-submit" @onclick="SubmitApplication" disabled="@IsProcessing">
                    @if (IsProcessing) { <span>Submitting...</span> } else { <span>Submit Application</span> }
                </button>
            </div>
        }
    </div>;
}

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; } = 0;
    private bool IsProcessing { get; set; } = false;
    private bool IsSubmitted { get; set; } = false;
    private int ApplicationId { get; set; }
    private List<string> Errors { get; set; } = new();

    // Step 1 fields
    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";

    // Step 2 fields
    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };

    // Step 3 fields
    private List<ReferenceModel> ReferenceEntries { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 fields
    private string CoverLetterText { get; set; } = "";

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (step < CurrentStep) return "completed";
        return "future";
    }

    private void NavigateToStep(int step)
    {
        if (step < CurrentStep)
        {
            CurrentStep = step;
            Errors.Clear();
        }
    }

    private void GoToStep(int step)
    {
        CurrentStep = step;
        Errors.Clear();
    }

    private async Task NextStep()
    {
        Errors.Clear();

        if (!ValidateCurrentStep())
            return;

        if (CurrentStep == 0)
        {
            IsProcessing = true;
            try
            {
                var isValidEmail = await ApplicationService.ValidateEmailAsync(Email);
                if (!isValidEmail)
                {
                    Errors.Add("The email address is not valid.");
                    return;
                }
            }
            finally
            {
                IsProcessing = false;
            }
        }

        CurrentStep++;
    }

    private void PreviousStep()
    {
        if (CurrentStep > 0)
        {
            CurrentStep--;
            Errors.Clear();
        }
    }

    private bool ValidateCurrentStep()
    {
        switch (CurrentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(FullName)) Errors.Add("Full name is required.");
                if (string.IsNullOrWhiteSpace(Email)) Errors.Add("Email is required.");
                if (string.IsNullOrWhiteSpace(Phone)) Errors.Add("Phone is required.");
                if (string.IsNullOrWhiteSpace(Address)) Errors.Add("Address is required.");
                break;
            case 1:
                for (int i = 0; i < WorkEntries.Count; i++)
                {
                    var entry = WorkEntries[i];
                    if (string.IsNullOrWhiteSpace(entry.Company)) Errors.Add($"Position {i + 1}: Company name is required.");
                    if (string.IsNullOrWhiteSpace(entry.Title)) Errors.Add($"Position {i + 1}: Job title is required.");
                    if (entry.StartDate == default) Errors.Add($"Position {i + 1}: Start date is required.");
                    if (string.IsNullOrWhiteSpace(entry.Description)) Errors.Add($"Position {i + 1}: Description is required.");
                }
                break;
            case 2:
                for (int i = 0; i < ReferenceEntries.Count; i++)
                {
                    var r = ReferenceEntries[i];
                    if (string.IsNullOrWhiteSpace(r.Name)) Errors.Add($"Reference {i + 1}: Name is required.");
                    if (string.IsNullOrWhiteSpace(r.Relationship)) Errors.Add($"Reference {i + 1}: Relationship is required.");
                    if (string.IsNullOrWhiteSpace(r.Email)) Errors.Add($"Reference {i + 1}: Email is required.");
                    if (string.IsNullOrWhiteSpace(r.Phone)) Errors.Add($"Reference {i + 1}: Phone is required.");
                }
                break;
            case 3:
                if (string.IsNullOrWhiteSpace(CoverLetterText)) Errors.Add("Cover letter is required.");
                break;
        }
        return !Errors.Any();
    }

    private async Task SubmitApplication()
    {
        IsProcessing = true;
        try
        {
            var personal = new PersonalInfo(FullName, Email, Phone, Address);
            var workHistory = new WorkHistory(WorkEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
            var references = ReferenceEntries.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(personal, workHistory, references, CoverLetterText);
            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
        }
        finally
        {
            IsProcessing = false;
        }
    }

    // Work Entry helpers
    private void AddWorkEntry() => WorkEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (WorkEntries.Count > 1)
            WorkEntries.RemoveAt(index);
    }

    private void UpdateWorkEntry(int index, string? company = null, string? title = null, string? description = null)
    {
        var entry = WorkEntries[index];
        if (company != null) entry.Company = company;
        if (title != null) entry.Title = title;
        if (description != null) entry.Description = description;
    }

    private void UpdateWorkEntryStartDate(int index, string? value)
    {
        if (DateTime.TryParse(value, out var date))
            WorkEntries[index].StartDate = date;
    }

    private void UpdateWorkEntryEndDate(int index, string? value)
    {
        if (DateTime.TryParse(value, out var date))
            WorkEntries[index].EndDate = date;
        else
            WorkEntries[index].EndDate = null;
    }

    private void ToggleCurrentPosition(int index, bool isCurrent)
    {
        WorkEntries[index].IsCurrent = isCurrent;
        if (isCurrent)
            WorkEntries[index].EndDate = null;
    }

    // Reference helpers
    private void AddReference()
    {
        if (ReferenceEntries.Count < 3)
            ReferenceEntries.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (ReferenceEntries.Count > 2)
            ReferenceEntries.RemoveAt(index);
    }

    private void UpdateReference(int index, string? name = null, string? relationship = null, string? email = null, string? phone = null)
    {
        var r = ReferenceEntries[index];
        if (name != null) r.Name = name;
        if (relationship != null) r.Relationship = relationship;
        if (email != null) r.Email = email;
        if (phone != null) r.Phone = phone;
    }

    // View models for mutable state
    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

