}

.btn-next,
.btn-submit {
    padding: 0.6rem 1.5rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 0.375rem;
    font-size: 1rem;
    cursor: pointer;
    margin-left: auto;
}

.btn-next:hover,
