    background: #0b5ed7;
}

.btn-next:disabled,
.btn-submit:disabled {
    background: #6c757d;
    cursor: not-allowed;
}

.btn-back {
    padding: 0.6rem 1.5rem;
    background: #6c757d;
    color: #fff;
    border: none;
    border-radius: 0.375rem;
    font-size: 1rem;
    cursor: pointer;
}

.btn-back:hover {
    background: #5a6268;
}

.btn-add {
    padding: 0.5rem 1rem;
    background: #198754;
    color: #fff;
    border: none;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-add:hover {
    background: #157347;
}

.btn-remove {
    padding: 0.3rem 0.75rem;
    background: #dc3545;
    color: #fff;
    border: none;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-remove:hover {
    background: #bb2d3b;
}

.btn-edit {
    padding: 0.25rem 0.75rem;
    background: transparent;
    color: #0d6efd;
    border: 1px solid #0d6efd;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-edit:hover {
    background: #0d6efd;
    color: #fff;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 200px !important;
}

.character-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.25rem;
}

/* Review Section */
.review-section {
    border: 1px solid #e0e0e0;
    border-radius: 0.5rem;
    padding: 1.5rem;
